/// Link 7 CoM x,y,z in link7 frame
/// Source: fr3_link7 inertial origin xyz="1.0517e-02 -4.252e-03 6.1597e-02"
pub const LINK7_COM: [f64; 3] = [0.010517, -0.004252, 0.061597];

// ── Gravity torque computation ────────────────────────────────────────────────

/// Result of the independent dynamics computation.
/// Completely separate from F × L conventional treatment.
#[derive(Debug, Clone)]
pub struct DynamicsTorqueResult {
    /// Gravity torque at A1 from all link masses + payload (N·m)
    pub tau_gravity_a1_nm: f64,
    /// Gravity torque at A2 from distal link masses + payload (N·m)
    pub tau_gravity_a2_nm: f64,
    /// Source declaration
    pub source: &'static str,
}

/// Compute gravity torques at A1 and A2 using published FR3 dynamic model.
///
/// At declared configuration θ₁=0 (arm pointing forward), θ₂=0 (horizontal):
/// - The world x-axis points forward along the arm
/// - Gravity acts in world -z direction
/// - Torque at a revolute joint with vertical axis = sum of (mass × g × horizontal_distance)
///   for all masses distal to that joint
///
/// For A1 (vertical axis at z=0.333m): all link masses + payload contribute
/// via their horizontal distance from the A1 axis.
///
/// For A2 (horizontal axis at the shoulder): only links 2-7 + payload
/// contribute, via their moment about the A2 axis.
///
/// At θ₁=0, θ₂=0 (neutral, arm fully extended forward and horizontal):
/// The computation proceeds in world frame at declared configuration.
pub fn compute_gravity_torques(payload_mass_kg: f64) -> DynamicsTorqueResult {
    // At θ₁=0, θ₂=0, the FR3 arm extends forward (+x world) from the base.
    // Joint A1 has a vertical axis (z). Gravity torque about A1 =
    // sum of (m_i × g × x_i_world) for all links and payload,
    // where x_i_world is the forward (x) distance of the CoM from A1 axis.
    //
    // At neutral config, the kinematic chain in world x:
    // A1 axis at x=0
    // Link1 CoM: x ≈ LINK1_COM[0] = 0.003875 m (small, near axis)
    // Link2-7 stack out along the arm
    //
    // We accumulate horizontal reach (x in world frame at θ=0) for each link CoM.
    // For simplicity at θ₁=0, θ₂=0, the arm extends in world +x.
    // The dominant contribution is the distal chain + payload.

    // Forward reach of each link's CoM at neutral configuration (world x)
    // These are computed from the kinematic chain at θ₁=0, θ₂=0.
    // At neutral, the chain is: base → up 0.333m → out along x.

    // Link 1 CoM horizontal distance from A1 (approximately the x component
    // of CoM in base frame at θ₁=0). Link1 CoM is at x≈0.003875 from joint.
    let link1_x = LINK1_COM[0]; // 0.003875 m

    // Links 2-7 are distal to joint1 at neutral config.
    // Approximate cumulative reach at neutral (θ₁=0, θ₂=0):
    // After joint1 (at 0.333m up), chain extends forward.
    // Joint2→3 offset: 0.316m forward (JOINT3_Y_M, becomes x at neutral)
    // Joint3→4 offset: 0.0825m (JOINT4_X_M)
    // Joint4→5 offset: 0.384m (JOINT5_Y_M, becomes x at neutral)
    // Joint5→7 + flange: ~0.088 + 0.107 = 0.195m

    // Cumulative x-positions of joint origins at neutral:
    let joint3_x_world = JOINT3_Y_M;          // 0.316 m
    let joint4_x_world = joint3_x_world + JOINT4_X_M; // 0.3985 m
    let joint5_x_world = joint4_x_world + JOINT5_Y_M; // 0.7825 m
    let flange_x_world = joint5_x_world + JOINT7_X_M + LINK8_Z_M; // 0.9695 m

    // CoM x-positions in world at neutral (approximate, dominant term is reach):
    let link2_x = JOINT3_Y_M + LINK2_COM[2]; // link2 CoM z is along the reach
    let link3_x = joint3_x_world + LINK3_COM[0]; // 0.316 + 0.027518
    let link4_x = joint4_x_world + LINK4_COM[1]; // 0.3985 + 0.104419 (y in link4 → x world)
    let link5_x = joint5_x_world + LINK5_COM[1]; // dominant reach term
    let link6_x = joint5_x_world + LINK6_COM[0]; // 0.7825 + 0.060149
    let link7_x = joint5_x_world + JOINT7_X_M + LINK7_COM[2]; // out to flange
    let payload_x = flange_x_world; // payload at end-effector

    // Gravity torque at A1 (vertical axis) = Σ m_i × g × x_i_world
    let tau_a1 =
        LINK1_MASS_KG * G_M_S2 * link1_x +
        LINK2_MASS_KG * G_M_S2 * link2_x +
        LINK3_MASS_KG * G_M_S2 * link3_x +
        LINK4_MASS_KG * G_M_S2 * link4_x +
        LINK5_MASS_KG * G_M_S2 * link5_x +
        LINK6_MASS_KG * G_M_S2 * link6_x +
        LINK7_MASS_KG * G_M_S2 * link7_x +
        payload_mass_kg * G_M_S2 * payload_x;

    // Gravity torque at A2 (horizontal axis at joint2, which is at x=0, z=0.333m).
    // A2 axis is horizontal (y-world at neutral). Torque about A2 =
    // Σ m_i × g × x_i_world for links 2-7 + payload (link1 is proximal, excluded).
    let tau_a2 =
        LINK2_MASS_KG * G_M_S2 * link2_x +
        LINK3_MASS_KG * G_M_S2 * link3_x +
        LINK4_MASS_KG * G_M_S2 * link4_x +
        LINK5_MASS_KG * G_M_S2 * link5_x +
        LINK6_MASS_KG * G_M_S2 * link6_x +
        LINK7_MASS_KG * G_M_S2 * link7_x +
        payload_mass_kg * G_M_S2 * payload_x;

    DynamicsTorqueResult {
        tau_gravity_a1_nm: tau_a1,
        tau_gravity_a2_nm: tau_a2,
        source: "FR3 dynamic model — frankarobotics/franka_description (Apache 2.0)",
    }
}
